import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  progress_completed INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  run_after INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, run_after, seq);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  beat_at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL; PRAGMA synchronous = FULL;');
  db.exec(SCHEMA);
  return db;
}
import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

/** Processing attempts allowed per job, counting the first. */
export const MAX_ATTEMPTS = 3;
/** Duration of one processing step. */
export const STEP_MS = 100;
/** Delay before a failed attempt is retried (must be within 250 ms to 2 s). */
export const RETRY_DELAY_MS = 1000;
export const TRANSIENT_ERROR = 'transient failure';
/** A worker heartbeat older than this means the worker is down. */
export const WORKER_STALE_MS = 3000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

/** A row of the `jobs` table, as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

/** The public JSON shape of a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function one(db: DatabaseSync, sql: string, params: (string | number | null)[] = []): JobRow | undefined {
  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
}

function many(db: DatabaseSync, sql: string): JobRow[] {
  return db.prepare(sql).all() as unknown as JobRow[];
}

function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return one(db, 'SELECT * FROM jobs WHERE id = ?', [id]);
}

export function findJobRowByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return one(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', [key]);
}

/** All jobs, newest first. */
export function listJobRows(db: DatabaseSync): JobRow[] {
  return many(db, 'SELECT * FROM jobs ORDER BY seq DESC');
}

export function insertJob(db: DatabaseSync, sub: Submission, idempotencyKey: string | null): JobRow {
  const id = randomUUID();
  const now = new Date().toISOString();
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                       idempotency_key, run_after, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  ).run(id, sub.input, sub.steps, sub.failAttempts, idempotencyKey, now, now);
  const row = getJobRow(db, id);
  if (!row) throw new Error(`inserted job ${id} not found`);
  return row;
}

/**
 * Claims the oldest queued job that is due, marking it running and counting the attempt.
 * Returns undefined when no job is due.
 */
export function claimNextJob(db: DatabaseSync, nowMs: number): JobRow | undefined {
  return transaction(db, () => {
    const next = one(db, "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1", [nowMs]);
    if (!next) return undefined;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?",
    ).run(new Date().toISOString(), next.seq);
    return one(db, 'SELECT * FROM jobs WHERE seq = ?', [next.seq]);
  });
}

/**
 * Called when a worker starts. Any job still `running` belonged to a worker that died mid-attempt.
 * If that attempt was the last allowed one, the job fails; otherwise it goes back to the queue.
 */
export function recoverInterruptedJobs(db: DatabaseSync): void {
  transaction(db, () => {
    const now = new Date().toISOString();
    db.prepare(
      "UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE status = 'running' AND attempts >= ?",
    ).run(TRANSIENT_ERROR, now, MAX_ATTEMPTS);
    db.prepare(
      "UPDATE jobs SET status = 'queued', run_after = 0, progress_completed = 0, updated_at = ? WHERE status = 'running'",
    ).run(now);
  });
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
}

export function markCompleted(db: DatabaseSync, id: string, output: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, progress_completed = steps, updated_at = ? WHERE id = ?",
  ).run(output, new Date().toISOString(), id);
}

export function markFailed(db: DatabaseSync, id: string, error: string): void {
  db.prepare("UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ?").run(
    error,
    new Date().toISOString(),
    id,
  );
}

export function requeue(db: DatabaseSync, id: string, runAfterMs: number): void {
  db.prepare("UPDATE jobs SET status = 'queued', run_after = ?, progress_completed = 0, updated_at = ? WHERE id = ?").run(
    runAfterMs,
    new Date().toISOString(),
    id,
  );
}

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
  ).run(nowMs);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.exec('DELETE FROM worker_heartbeat');
}

export function isWorkerUp(db: DatabaseSync, nowMs: number): boolean {
  const row = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
  return row !== undefined && nowMs - Number(row.beat_at) <= WORKER_STALE_MS;
}
import type { DatabaseSync } from 'node:sqlite';
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  MAX_ATTEMPTS,
  RETRY_DELAY_MS,
  STEP_MS,
  TRANSIENT_ERROR,
  claimNextJob,
  clearHeartbeat,
  markCompleted,
  markFailed,
  recoverInterruptedJobs,
  requeue,
  setProgress,
  writeHeartbeat,
  type JobRow,
} from './jobs.ts';

const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Runs one attempt of a job that has already been marked running and had its attempt counted. */
async function runAttempt(db: DatabaseSync, job: JobRow): Promise<void> {
  const attempt = job.attempts;

  // Simulated transient failure: the attempt fails at its first step, before any progress.
  if (attempt <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (attempt >= MAX_ATTEMPTS) markFailed(db, job.id, TRANSIENT_ERROR);
    else requeue(db, job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping && step < job.steps) {
      // Shutting down mid-attempt: hand the job back so the next worker runs it again.
      requeue(db, job.id, 0);
      return;
    }
    setProgress(db, job.id, step);
  }
  markCompleted(db, job.id, job.input.toUpperCase());
}

recoverInterruptedJobs(db);
writeHeartbeat(db, Date.now());
const heartbeat = setInterval(() => writeHeartbeat(db, Date.now()), HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = claimNextJob(db, Date.now());
    if (job) await runAttempt(db, job);
    else await sleep(IDLE_POLL_MS);
  } catch (e) {
    console.error('worker error:', e);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeat);
clearHeartbeat(db);
db.close();
console.log('worker stopped');
process.exit(0);

import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import {
  findJobRowByKey,
  getJobRow,
  insertJob,
  isWorkerUp,
  listJobRows,
  toJob,
  type JobRow,
  type Submission,
} from './jobs.ts';
import { parseSubmission, type FieldError } from './validation.ts';

const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error = fields ? { code, message, fields } : { code, message };
  send(res, status, { error });
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allow}.`);
}

/** Reads the body. Resolves to null if it exceeds MAX_BODY_BYTES (the rest is discarded). */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function sameSubmission(row: JobRow, sub: Submission): boolean {
  return row.input === sub.input && row.steps === sub.steps && row.fail_attempts === sub.failAttempts;
}

async function createJobRoute(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawBody = await readBody(req);
  const idemHeader = req.headers['idempotency-key'];
  const idemValue = Array.isArray(idemHeader) ? idemHeader.join(', ') : idemHeader;
  const parsed = parseSubmission(req.headers['content-type'], rawBody, idemValue);
  if (!parsed.ok) {
    return sendError(res, 400, 'invalid_request', `Invalid request: ${parsed.fields.map((f) => f.field).join(', ')}.`, parsed.fields);
  }

  const { submission, idempotencyKey } = parsed;
  if (idempotencyKey !== null) {
    const existing = findJobRowByKey(db, idempotencyKey);
    if (existing) {
      if (sameSubmission(existing, submission)) return send(res, 200, toJob(existing));
      return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    }
  }

  send(res, 201, toJob(insertJob(db, submission, idempotencyKey)));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return send(res, 200, { status: 'ok', worker: isWorkerUp(db, Date.now()) ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: listJobRows(db).map(toJob) });
    if (method === 'POST') return createJobRoute(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const row = getJobRow(db, id);
    if (!row) return sendError(res, 404, 'not_found', 'No such job.');
    return send(res, 200, toJob(row));
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  const exit = () => {
    try {
      db.close();
    } finally {
      process.exit(0);
    }
  };
  server.close(exit);
  server.closeAllConnections();
  setTimeout(exit, 3000).unref();
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);
import type { Submission } from './jobs.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type ParseResult =
  | { ok: true; submission: Submission; idempotencyKey: string | null }
  | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
export const MAX_INPUT_LENGTH = 1000;

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function isIntegerIn(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

/**
 * Validates a submission. `contentType` and `idempotencyKey` are the raw header values, and
 * `rawBody` is the body text, or null when the body was too large to read.
 * Every offending field is reported, not just the first.
 */
export function parseSubmission(
  contentType: string | undefined,
  rawBody: string | null,
  idempotencyKey: string | undefined,
): ParseResult {
  const fields: FieldError[] = [];

  if (idempotencyKey !== undefined && !IDEMPOTENCY_KEY.test(idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'must be 1-128 characters of A-Z, a-z, 0-9, "_" or "-"' });
  }

  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return { ok: false, fields };
  }
  if (rawBody === null) {
    fields.push({ field: 'body', message: 'request body is too large' });
    return { ok: false, fields };
  }

  let body: unknown;
  try {
    body = JSON.parse(rawBody);
  } catch {
    fields.push({ field: 'body', message: 'body must be valid JSON' });
    return { ok: false, fields };
  }
  if (!isPlainObject(body)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return { ok: false, fields };
  }

  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  const { input, steps = 5, failAttempts = 0 } = body as Record<string, unknown>;

  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input is required and must be a string' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `input must be 1-${MAX_INPUT_LENGTH} characters` });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be only whitespace' });
  }

  if (!isIntegerIn(steps, 1, 20)) fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
  if (!isIntegerIn(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });

  if (fields.length > 0) return { ok: false, fields };
  return {
    ok: true,
    submission: { input: input as string, steps: steps as number, failAttempts: failAttempts as number },
    idempotencyKey: idempotencyKey ?? null,
  };
}
