<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form">
    <label>Input
      <input data-testid="job-input" name="input" type="text" autocomplete="off">
    </label>
    <label>Steps
      <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" value="5">
    </label>
    <label>Fail attempts
      <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" value="0">
    </label>
    <button data-testid="job-submit" type="submit">Submit</button>
  </form>

  <div data-testid="form-error" role="alert" id="form-error" class="error"></div>

  <ul data-testid="job-list" id="job-list"></ul>

  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const inputField = document.querySelector('[data-testid="job-input"]');
    const stepsField = document.querySelector('[data-testid="job-steps"]');
    const failField = document.querySelector('[data-testid="job-fail-attempts"]');
    const submitButton = document.querySelector('[data-testid="job-submit"]');
    const errorBox = document.getElementById('form-error');
    const list = document.getElementById('job-list');

    // Sends numeric text as a number so the API validates it as one; anything else is sent as-is
    // so the API rejects it and names the field.
    function numberOrRaw(text) {
      const t = text.trim();
      return /^[+-]?\d+(\.\d+)?([eE][+-]?\d+)?$/.test(t) ? Number(t) : text;
    }

    function describeError(data, status) {
      const err = data && data.error;
      if (!err) return `Request failed (HTTP ${status}).`;
      let message = err.message || err.code || 'Request failed.';
      if (Array.isArray(err.fields) && err.fields.length > 0) {
        message += ' ' + err.fields.map((f) => `${f.field}: ${f.message}`).join('; ');
      }
      return message;
    }

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      errorBox.textContent = '';
      submitButton.disabled = true;
      try {
        const res = await fetch('/api/jobs', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({
            input: inputField.value,
            steps: numberOrRaw(stepsField.value),
            failAttempts: numberOrRaw(failField.value),
          }),
        });
        const data = await res.json().catch(() => null);
        if (res.ok) {
          inputField.value = '';
          await refresh();
        } else {
          errorBox.textContent = describeError(data, res.status);
        }
      } catch (e) {
        errorBox.textContent = 'Could not reach the server.';
      } finally {
        submitButton.disabled = false;
      }
    });

    const items = new Map();

    function createItem(id) {
      const li = document.createElement('li');
      li.setAttribute('data-testid', 'job-item');
      li.dataset.jobId = id;

      const row = document.createElement('div');
      row.className = 'row';
      const status = document.createElement('span');
      status.setAttribute('data-testid', 'job-status');
      const progress = document.createElement('span');
      progress.setAttribute('data-testid', 'job-progress');
      progress.className = 'muted';
      row.append(status, progress);

      const input = document.createElement('div');
      input.className = 'input';

      const result = document.createElement('div');
      result.setAttribute('data-testid', 'job-result');

      li.append(row, input, result);
      return li;
    }

    function updateItem(li, job) {
      li.querySelector('[data-testid="job-status"]').textContent = job.status;
      li.querySelector('[data-testid="job-status"]').className = `status-${job.status}`;
      li.querySelector('[data-testid="job-progress"]').textContent = `${job.progress.completed}/${job.progress.total}`;
      li.querySelector('.input').textContent = job.input;
      let text = '';
      if (job.status === 'completed' && job.result) text = job.result.output;
      else if (job.status === 'failed' && job.error) text = job.error;
      li.querySelector('[data-testid="job-result"]').textContent = text;
    }

    function render(jobs) {
      const seen = new Set();
      const nodes = [];
      for (const job of jobs) {
        let li = items.get(job.id);
        if (!li) {
          li = createItem(job.id);
          items.set(job.id, li);
        }
        updateItem(li, job);
        seen.add(job.id);
        nodes.push(li);
      }
      for (const [id, li] of items) {
        if (!seen.has(id)) {
          li.remove();
          items.delete(id);
